// relay/test/vectors/derivation.json is a copy of the phase-03 reference vectors (generated by the
// independent Python script). The Worker tests import the copy through the bundler; this test makes
// sure the copy cannot drift from the source. Fix a failure with `npm run sync-vectors`.
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const relayRoot = resolve(fileURLToPath(import.meta.url), '../..');
const source = resolve(relayRoot, '../server/modules/remote/tests/vectors/derivation.json');
const copy = resolve(relayRoot, 'test/vectors/derivation.json');
const sha256 = (path: string): string => createHash('sha256').update(readFileSync(path)).digest('hex');

describe('reference vectors', () => {
  it('the relay copy has the same SHA-256 as the phase-03 source', () => {
    expect(sha256(copy)).toBe(sha256(source));
  });

  it('carries the gate vectors the Worker must reproduce', () => {
    const v = JSON.parse(readFileSync(copy, 'utf8')) as { gate: Record<string, string>; link: { roomId: string }; pair: { pairRoomId: string } };
    expect(v.gate.relaySecret).toBe('test-relay-secret');
    expect(v.gate.link).toMatch(/^[0-9a-f]{64}$/);
    expect(v.gate.pair).toMatch(/^[0-9a-f]{64}$/);
    expect(v.link.roomId).toMatch(/^[0-9a-f]{32}$/);
    expect(v.pair.pairRoomId).toMatch(/^[0-9a-f]{32}$/);
  });
});
